package com.careflow.hospital.reservations;

import com.careflow.hospital.audit.AuditService;import com.careflow.hospital.departments.*;import com.careflow.hospital.doctors.*;import com.careflow.hospital.patients.*;import com.careflow.hospital.scheduling.*;import com.careflow.hospital.shared.DomainException;import java.time.*;import java.util.*;import org.springframework.dao.DataIntegrityViolationException;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class ReservationService {private final SlotReservationRepository reservations;private final PatientRepository patients;private final DoctorRepository doctors;private final DepartmentRepository departments;private final SlotGenerationService slots;private final AuditService audit;public ReservationService(SlotReservationRepository reservations,PatientRepository patients,DoctorRepository doctors,DepartmentRepository departments,SlotGenerationService slots,AuditService audit){this.reservations=reservations;this.patients=patients;this.doctors=doctors;this.departments=departments;this.slots=slots;this.audit=audit;}
 @Transactional public ReservationDtos.View create(UUID userId,ReservationDtos.Create request){Instant now=Instant.now();reservations.expireBefore(now);var patient=patient(userId);var doctor=doctors.findByIdForUpdate(request.doctorId()).filter(Doctor::isActive).orElseThrow(()->new DomainException(HttpStatus.NOT_FOUND,"DOCTOR_NOT_FOUND","Active doctor was not found."));var department=departments.findById(doctor.getDepartmentId()).filter(Department::isActive).orElseThrow(()->new DomainException(HttpStatus.CONFLICT,"DEPARTMENT_UNAVAILABLE","Doctor department is unavailable."));LocalDate date=request.startsAt().atZone(zone(department.getTimezone())).toLocalDate();var slot=slots.generate(department.getId(),doctor.getId(),date).stream().filter(s->s.startsAt().equals(request.startsAt())).findFirst().orElseThrow(()->new DomainException(HttpStatus.CONFLICT,"SLOT_UNAVAILABLE","The requested slot is no longer available."));SlotReservation reservation;try{reservation=reservations.saveAndFlush(new SlotReservation(patient.getId(),doctor.getId(),slot.startsAt(),slot.endsAt(),now.plusSeconds(300)));}catch(DataIntegrityViolationException e){throw new DomainException(HttpStatus.CONFLICT,"SLOT_ALREADY_BOOKED","The selected appointment slot is no longer available.");}audit.record(userId,"SLOT_RESERVED","SLOT_RESERVATION",reservation.getId(),"SUCCESS");return view(reservation);}
 @Transactional(readOnly=true) public List<ReservationDtos.View> list(UUID userId){var patient=patient(userId);return reservations.findAllByPatientIdOrderByCreatedAtDesc(patient.getId()).stream().map(this::view).toList();}
 @Transactional public void cancel(UUID userId,UUID reservationId){var patient=patient(userId);var reservation=reservations.findById(reservationId).filter(r->r.getPatientId().equals(patient.getId())).orElseThrow(()->new DomainException(HttpStatus.NOT_FOUND,"RESERVATION_NOT_FOUND","Reservation was not found."));if(!"ACTIVE".equals(reservation.getStatus())||!reservation.getExpiresAt().isAfter(Instant.now()))throw new DomainException(HttpStatus.CONFLICT,"RESERVATION_NOT_ACTIVE","Reservation is no longer active.");reservation.cancel();audit.record(userId,"SLOT_RESERVATION_CANCELLED","SLOT_RESERVATION",reservationId,"SUCCESS");}
 private Patient patient(UUID userId){return patients.findByUserId(userId).filter(Patient::isProfileComplete).orElseThrow(()->new DomainException(HttpStatus.CONFLICT,"PATIENT_PROFILE_REQUIRED","Complete the patient profile before reserving a slot."));}private ZoneId zone(String value){try{return ZoneId.of(value);}catch(DateTimeException e){throw new DomainException(HttpStatus.INTERNAL_SERVER_ERROR,"INVALID_DEPARTMENT_TIMEZONE","Department timezone is invalid.");}}private ReservationDtos.View view(SlotReservation r){String status="ACTIVE".equals(r.getStatus())&&!r.getExpiresAt().isAfter(Instant.now())?"EXPIRED":r.getStatus();return new ReservationDtos.View(r.getId(),r.getDoctorId(),r.getStartsAt(),r.getEndsAt(),r.getExpiresAt(),status);}}
